import{_ as o,o as d,c,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-MSAVE-Command.md","filePath":"manual-zh/Matrix-MSAVE-Command.md","lastUpdated":1785684581000}'),_={name:"manual-zh/Matrix-MSAVE-Command.md"};function r(t,e,A,n,S,E){return d(),c("div",null,[...e[0]||(e[0]=[a(`<h4 id="_16-4-12-msave-命令" tabindex="-1">16.4.12 <code>MSAVE</code> 命令 <a class="header-anchor" href="#_16-4-12-msave-命令" aria-label="Permalink to &quot;16.4.12 \`MSAVE\` 命令&quot;">​</a></h4><pre><code>MSAVE _expression_
      /TYPE={COV _|_ CORR _|_ MEAN _|_ STDDEV _|_ N _|_ COUNT}
      [/FACTOR=_expression_]
      [/SPLIT=_expression_]
      [/OUTFILE=_file_]
      [/VARIABLES=_variable_ …]
      [/SNAMES=_variable_ …]
      [/FNAMES=_variable_ …].
</code></pre><p><code>MSAVE</code> 命令求值命令名之后紧跟的 <em>expression</em>，并将结果矩阵写入矩阵文件（参见 <a href="./Matrix-Files">Matrix Files</a>）。</p><p><code>TYPE</code> 子命令是必需的。它指定与之同时写入的 <code>ROWTYPE_</code>。</p><p>当且仅当矩阵文件分别含有因子变量或拆分变量时，<code>FACTOR</code> 和 <code>SPLIT</code> 子命令在第一个 <code>MSAVE</code> 上是必需的。此后，它们的值会按语法顺序从一个 <code>MSAVE</code> 命令沿用到下一个作为默认值。每个子命令接受一个表达式，该表达式必须求值为一个向量，其条目数与矩阵的因子变量或拆分变量数分别相同。每个 <code>MSAVE</code> 只写入因子和拆分变量的一种组合的数据，因此可能需要多个 <code>MSAVE</code> 命令（或在循环内的一个）来写入完整的一组数据。</p><p>其余 <code>MSAVE</code> 子命令定义矩阵文件的格式。在给定的矩阵程序内，所有 <code>MSAVE</code> 命令都写入同一个矩阵文件，因此这些子命令只在矩阵程序内的第一个 <code>MSAVE</code> 命令上有意义。（如果它们在后面的 <code>MSAVE</code> 命令上再次给出，则必须与第一个上的值相同。）</p><p><code>OUTFILE</code> 子命令指定要写入的矩阵文件的名称或句柄。输出必须写入外部文件，而不是数据集或活动文件。</p><p><code>VARIABLES</code> 子命令指定要写入矩阵文件的连续变量名称的逗号分隔列表。<code>TO</code> 关键字可用于定义带有连续整数后缀的变量名。这些名称成为矩阵文件中的列名以及 <code>VARNAME_</code> 中出现的名称。<code>ROWTYPE_</code> 和 <code>VARNAME_</code> 不允许出现在 <code>VARIABLES</code> 上。如果省略 <code>VARIABLES</code>，则 PSPP 使用名称 <code>COL1</code>、<code>COL2</code> 等。</p><p><code>FNAMES</code> 子命令可用于提供因子变量名的逗号分隔列表。默认名称为 <code>FAC1</code>、<code>FAC2</code> 等。</p><p><code>SNAMES</code> 子命令可以提供拆分变量名的逗号分隔列表。默认名称为 <code>SPL1</code>、<code>SPL2</code> 等。</p>`,10)])])}const i=o(_,[["render",r]]);export{s as __pageData,i as default};
